coding.referenceSolution:
function toolResultMessage(response, results) {
  const calls = response.content.filter((b) => b.type === "tool_use");
  return {
    role: "user",
    content: calls.map((call) =>
      call.name in results
        ? { type: "tool_result", tool_use_id: call.id, content: results[call.name] }
        : { type: "tool_result", tool_use_id: call.id, content: "unknown tool", is_error: true }
    ),
  };
}

